// PixelLab sprites, generated by scripts/art/registry2.py from assets/v4/sprites/meta.json.
// Each image: size at 2x, the footprint centre inside it (ax, ay) and the scale that makes its
// ground slab fill the footprint. Buildings without an entry use code-drawn sprites.
export type Tier = 1 | 2 | 3 | 4 | 5
export type SpriteImage = {
  src: number
  w: number
  h: number
  ax: number
  ay: number
  scale: number
}
const img = (
  src: number,
  w: number,
  h: number,
  ax: number,
  ay: number,
  scale: number,
): SpriteImage => ({
  src,
  w,
  h,
  ax,
  ay,
  scale,
})
